package stylesheet

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// Named colours (decision of 12/10/2026): a .ui page may name a colour by its name — the 148 named
// colours of CSS Color 4 and the names only Figma's colour list has, one dictionary (named.go,
// generated by named_gen.go). In markup a named colour is a fixed colour like white and black: the same
// in light and dark, an alpha /N allowed, lighter -N and stronger +N refused (they are toward and away
// from a mode's canvas: operators.go). In router.colors a named colour seeds a role as its hex would
// (brand: "cerulean"), and the role takes -N and +N. A token may not be named like one.

// NamedColour is the value of a named colour, #rrggbb. ok is false for any other word: a token, a typo,
// a name written another way (slate-gray, SlateGray) and the Figma names that only rename a CSS colour
// (navy-blue).
func NamedColour(name string) (hex string, ok bool) {
	hex, ok = namedColours[name]
	return hex, ok
}

// NamedColours lists the names of the dictionary, sorted.
func NamedColours() []string { return sortedKeys(namedColours) }

// fixedColour is the value of a colour that is the same in every mode: white and black as the table
// has always written them (#fff, #000), or a named colour.
func fixedColour(name string) (string, bool) {
	if hex, ok := fixedColors[name]; ok {
		return hex, true
	}
	return NamedColour(name)
}

// namedLetters is every name by its letters (letters): two names never share them (named_gen.go
// checks it), so a word with a name's letters means that name.
var namedLetters = lettersOf(namedColours)

func lettersOf(names map[string]string) map[string]string {
	out := make(map[string]string, len(names))
	for name := range names {
		out[letters(name)] = name
	}
	return out
}

// letters is a word without case and without the marks between its words: SlateGray, slate-gray and
// slate_gray are slategray.
func letters(word string) string {
	var b strings.Builder
	for _, c := range strings.ToLower(word) {
		if c != '-' && c != '_' && c != ' ' {
			b.WriteRune(c)
		}
	}
	return b.String()
}

// aliasLetters is every Figma name that only renames a CSS colour by its letters (letters): navyblue,
// Navy_Blue and navy-blue are all navy-blue. No name of the dictionary has the letters of one
// (TestNamedAliasesWrittenAnyWay checks it), so the two lookups never meet.
var aliasLetters = lettersOf(namedAliases)

// namedOtherwise reads a word that means a named colour but is not its name: a Figma name that only
// renames a CSS colour (navy-blue is navy), however its letters are written (navyblue, Navy-Blue), or a
// name with its letters written another way — with a hyphen CSS does not write (slate-gray), in
// capitals (SlateGray), run together where Figma hyphenates (burntorange). It returns the name to write
// and the sentence that says why.
func namedOtherwise(word string) (name, why string, ok bool) {
	if alias, ok := aliasLetters[letters(word)]; ok {
		name := namedAliases[alias]
		return name, word + " không phải tên màu: đó là tên Figma đặt cho " + name + " (" + namedColours[name] + ") của CSS; viết " + name, true
	}
	if name, ok := namedLetters[letters(word)]; ok && name != word {
		return name, word + " không phải tên màu: tên là " + name + " (" + namedColours[name] + "), chữ thường, gạch nối đúng như tên; viết " + name, true
	}
	return "", "", false
}

// misnamedColour refuses, in markup, a colour written as a name it is not (namedOtherwise), with the
// name to write: the value as written with the name in place of the word (navy-blue/50 is navy/50). An
// operator goes with it as written; the name then says it takes none. nil for any other word.
func misnamedColour(in Intent, v, base string) *Problem {
	name, why, ok := namedOtherwise(base)
	if !ok {
		return nil
	}
	p := problem(in, in.Name+"=\""+v+"\": "+why)
	p.Suggestion = name + strings.TrimPrefix(v, base)
	return p
}

// namedShadeProblem refuses the old shade .N of a named colour (tomato.70): it is one colour, the same
// in light and dark, with no -N or +N either. Its alpha is written /N, and a role seeded by it takes -N
// and +N. valid says the digits are a whole number from 0 to 100.
func namedShadeProblem(in Intent, v, base, shade string, valid, hasAlpha bool) *Problem {
	alpha, lighter := base+"/N", "brand-30"
	if valid {
		n, _ := whole(shade, 0, 100)
		alpha, lighter = base+"/"+shade, "brand-"+strconv.Itoa(100-n)
	}
	p := problem(in, said(in, v)+base+" là màu có tên, cố định ở sáng và tối, không có -N, +N: độ hiện viết "+alpha+
		"; cần nhạt hơn hay đậm hơn thì cho một token màu ấy: router.colors({ brand: \""+base+"\" }) rồi viết "+lighter+", brand+"+strconv.Itoa(StrongStep))
	if valid && !hasAlpha {
		p.Suggestion = alpha
	}
	return p
}

// namedColourWords is what the table's messages say a named colour is.
func namedColourWords() string {
	return "màu có tên, cố định ở sáng và tối: white, black, tomato, cerulean… (" + strconv.Itoa(len(namedColours)) + " tên màu của CSS và Figma)"
}

// namedSeed reads a colour router.colors writes as a name: its value when it names a colour, an error
// when it names one otherwise (navy-blue, slate-gray). named is false for a value that is no name at
// all, for the caller to read as hex.
func namedSeed(token, mode, value string) (hex string, named bool, err error) {
	if hex, ok := NamedColour(value); ok {
		return hex, true, nil
	}
	if _, why, ok := namedOtherwise(value); ok {
		which := ""
		if mode != "" {
			which = " (" + mode + ")"
		}
		return "", true, fmt.Errorf("router.colors: %q%s là %q: %s", token, which, value, why)
	}
	return "", false, nil
}

// namedTokenError refuses a token named like a named colour: the name already means that colour, the
// same in light and dark, and a token is a role the site re-values.
func namedTokenError(name string) error {
	hex, ok := NamedColour(name)
	if !ok {
		return nil
	}
	return fmt.Errorf("router.colors: %q đã là tên một màu (%s), cùng một màu ở sáng và tối: đặt tên token theo vai trò (brand, accent…) và cho nó màu ấy: router.colors({ brand: %q })", name, hex, name)
}

// nearestColours names the named colours and tokens closest to a word that is neither, for an
// error ("; gần nhất: tomato"): at most three, those fewest edits away, within a third of the word's
// length (two at least). "" when none is that close.
func nearestColours(word string, tokens []string) string {
	limit := max(len(word)/3, 2)
	best := limit + 1
	var near []string
	candidates := append(NamedColours(), tokens...)
	sort.Strings(candidates)
	for _, candidate := range candidates {
		d := editDistance(word, candidate, best)
		switch {
		case d < best:
			best, near = d, []string{candidate}
		case d == best && d <= limit && indexOf(near, candidate) < 0:
			near = append(near, candidate)
		}
	}
	if len(near) == 0 {
		return ""
	}
	if len(near) > 3 {
		near = near[:3]
	}
	return "; gần nhất: " + strings.Join(near, ", ")
}

// editDistance is the number of single-letter edits between two words (Levenshtein), or more than
// limit as soon as it is.
func editDistance(a, b string, limit int) int {
	if d := len(a) - len(b); d > limit || -d > limit {
		return limit + 1
	}
	previous := make([]int, len(b)+1)
	for j := range previous {
		previous[j] = j
	}
	for i := 1; i <= len(a); i++ {
		current := make([]int, len(b)+1)
		current[0] = i
		lowest := current[0]
		for j := 1; j <= len(b); j++ {
			cost := 1
			if a[i-1] == b[j-1] {
				cost = 0
			}
			current[j] = min(previous[j]+1, current[j-1]+1, previous[j-1]+cost)
			lowest = min(lowest, current[j])
		}
		if lowest > limit {
			return limit + 1
		}
		previous = current
	}
	return previous[len(b)]
}
